{
 "description": "Runner is the Schema for the runners API",
 "properties": {
  "spec": {
   "description": "RunnerSpec defines the desired state of Runner",
   "properties": {
    "authentication": {
     "description": "Authentication configures how the runner authenticates to GitLab.",
     "properties": {
      "access_token": {
       "description": "AccessToken is a personal, group, or project access token with the\n\"create_runner\" scope. Required for the managed mode.",
       "properties": {
        "secret_key_ref": {
         "description": "SecretKeyRef reads the token from a Secret in the runner's namespace. The\nreferenced key defaults to \"token\" when Key is omitted. Optional is\nhonoured: when true, a missing secret or key resolves to an empty token\ninstead of failing.",
         "properties": {
          "key": {
           "description": "Key holding the token. Defaults to \"token\" when omitted.",
           "type": "string"
          },
          "name": {
           "description": "Name of the Secret in the runner's namespace.",
           "minLength": 1,
           "type": "string"
          },
          "optional": {
           "description": "Optional, when true, lets a missing secret or key resolve to an empty\ntoken instead of failing.",
           "type": "boolean"
          }
         },
         "required": [
          "name"
         ],
         "type": "object"
        },
        "value": {
         "description": "Value is the literal token. Convenient for testing; prefer SecretKeyRef\nin production so the token is not stored in the object spec.",
         "type": "string"
        }
       },
       "type": "object",
       "x-kubernetes-validations": [
        {
         "message": "set either value or secret_key_ref, not both",
         "rule": "(has(self.value) \u0026\u0026 size(self.value) != 0) != has(self.secret_key_ref)"
        }
       ]
      },
      "create_options": {
       "description": "CreateOptions describes the runner to create. When set, the operator runs\nin managed mode and owns the runner's lifecycle on GitLab.",
       "properties": {
        "access_level": {
         "type": "string"
        },
        "description": {
         "type": "string"
        },
        "group_id": {
         "description": "GroupID is required when RunnerType is group_type.",
         "type": "integer"
        },
        "locked": {
         "type": "boolean"
        },
        "maintenance_note": {
         "type": "string"
        },
        "maximum_timeout": {
         "type": "integer"
        },
        "paused": {
         "type": "boolean"
        },
        "project_id": {
         "description": "ProjectID is required when RunnerType is project_type.",
         "type": "integer"
        },
        "run_untagged": {
         "type": "boolean"
        },
        "runner_type": {
         "description": "RunnerType selects the scope of the runner to create.",
         "enum": [
          "instance_type",
          "group_type",
          "project_type"
         ],
         "type": "string"
        },
        "tag_list": {
         "items": {
          "type": "string"
         },
         "type": "array"
        }
       },
       "required": [
        "runner_type"
       ],
       "type": "object",
       "x-kubernetes-validations": [
        {
         "message": "group_type runner requires group_id",
         "rule": "self.runner_type != 'group_type' || has(self.group_id)"
        },
        {
         "message": "project_type runner requires project_id",
         "rule": "self.runner_type != 'project_type' || has(self.project_id)"
        }
       ]
      },
      "token": {
       "description": "Token is the pre-created runner authentication token (\"glrt-...\") used in\nbring-your-own mode. Mutually exclusive with the managed CreateOptions.",
       "properties": {
        "secret_key_ref": {
         "description": "SecretKeyRef reads the token from a Secret in the runner's namespace. The\nreferenced key defaults to \"token\" when Key is omitted. Optional is\nhonoured: when true, a missing secret or key resolves to an empty token\ninstead of failing.",
         "properties": {
          "key": {
           "description": "Key holding the token. Defaults to \"token\" when omitted.",
           "type": "string"
          },
          "name": {
           "description": "Name of the Secret in the runner's namespace.",
           "minLength": 1,
           "type": "string"
          },
          "optional": {
           "description": "Optional, when true, lets a missing secret or key resolve to an empty\ntoken instead of failing.",
           "type": "boolean"
          }
         },
         "required": [
          "name"
         ],
         "type": "object"
        },
        "value": {
         "description": "Value is the literal token. Convenient for testing; prefer SecretKeyRef\nin production so the token is not stored in the object spec.",
         "type": "string"
        }
       },
       "type": "object",
       "x-kubernetes-validations": [
        {
         "message": "set either value or secret_key_ref, not both",
         "rule": "(has(self.value) \u0026\u0026 size(self.value) != 0) != has(self.secret_key_ref)"
        }
       ]
      }
     },
     "type": "object",
     "x-kubernetes-validations": [
      {
       "message": "one of token or create_options must be set",
       "rule": "has(self.token) || has(self.create_options)"
      },
      {
       "message": "set either a pre-created authentication token or create_options, not both",
       "rule": "!(has(self.token) \u0026\u0026 has(self.create_options))"
      },
      {
       "message": "create_options requires access_token",
       "rule": "!has(self.create_options) || has(self.access_token)"
      },
      {
       "message": "access_token is only used with create_options (managed mode)",
       "rule": "!has(self.access_token) || has(self.create_options)"
      }
     ]
    },
